        ["Para o serviço de suporte ao Bluetooth. Fones, controles e mouses Bluetooth deixam de conectar."] = "Detiene el servicio de soporte de Bluetooth. Los auriculares, controles y mouse Bluetooth dejan de conectarse.",
        ["Desligar o Hyper-V"] = "Desactivar Hyper-V",
        ["Para os serviços de máquinas virtuais. WSL 2, Docker e o Sandbox do Windows precisam deles."] = "Detiene los servicios de máquinas virtuales. WSL 2, Docker y Windows Sandbox los necesitan.",
        ["Desligar os serviços do Xbox"] = "Desactivar los servicios de Xbox",
        ["Para a Xbox Live e o salvamento na nuvem de jogos do app Xbox. Controles continuam funcionando."] = "Detiene Xbox Live y el guardado en la nube de los juegos de la aplicación Xbox. Los controles siguen funcionando.",
        ["Jogos do Game Pass/Xbox app podem não abrir com eles desligados."] = "Los juegos de Game Pass/aplicación Xbox pueden no abrir con ellos desactivados.",
        ["Em Modo Jogo"] = "En Modo Juego",
        ["Exclusões de pastas de jogos e liga/desliga da proteção em tempo real ficam em Modo Jogo → Sistema."] = "Las exclusiones de carpetas de juegos y activar/desactivar la protección en tiempo real están en Modo Juego → Sistema.",
